// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 _val, address caller) public {
        if (caller == address(0)) caller = address(1);

        vm.deal(caller, 1 ether);

        vm.prank(caller);
        c.Initialized();

        bool ok;
        vm.prank(caller);
        try c.SetMinSum(_val) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
